CREATE TABLE IF NOT EXISTS restaurants (id SERIAL PRIMARY KEY,name TEXT NOT NULL,cuisine TEXT NOT NULL,eta TEXT NOT NULL,image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS menu_items (id SERIAL PRIMARY KEY,restaurant_id INT REFERENCES restaurants(id),name TEXT NOT NULL,description TEXT NOT NULL,price NUMERIC(10,2) NOT NULL,image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY,customer_name TEXT NOT NULL,items JSONB NOT NULL,total NUMERIC(10,2) NOT NULL,status TEXT NOT NULL DEFAULT 'confirmed',created_at TIMESTAMPTZ DEFAULT now());
